namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public required string DepartmentCode { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
    public required string Description { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Code = "ENG", Name = "English", Description = "Literature, writing, and communication studies." },
            new() { Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Code = "HIST", Name = "History", Description = "Exploration of past events, cultures, and civilizations." },
        ];

        _courses =
        [
            new()
            {
                Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
                Description = "An introductory course covering fundamental concepts of programming, data structures, and algorithmic thinking. Students will learn to write programs in Python and gain exposure to core computing principles.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS",
                InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT and has over 15 years of experience teaching introductory programming. Her research focuses on CS education and programming language design.",
                IsFeatured = true
            },
            new()
            {
                Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithms (sorting, searching, dynamic programming). Emphasis on efficiency analysis and practical implementation.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentCode = "CS",
                InstructorName = "Prof. Alan Turing", InstructorBio = "Prof. Turing is a distinguished professor specializing in algorithm design and computational complexity. He has published extensively in top-tier journals and mentored dozens of graduate students.",
                IsFeatured = true
            },
            new()
            {
                Id = 3, Code = "CS 310", Title = "Database Systems",
                Description = "Introduction to relational database design, SQL, normalization, transaction processing, and query optimization. Includes a semester-long project building a database-driven application.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentCode = "CS",
                InstructorName = "Dr. Grace Hopper", InstructorBio = "Dr. Hopper has spent 20 years in both industry and academia. She previously worked as a database architect at a Fortune 500 company before joining the faculty.",
                IsFeatured = false
            },
            new()
            {
                Id = 4, Code = "MATH 101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics. Prepares students for advanced mathematics courses.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "MATH",
                InstructorName = "Dr. Euclid Pythagoras", InstructorBio = "Dr. Pythagoras is a tenured professor with a passion for making calculus accessible. He has authored two bestselling textbooks on introductory mathematics.",
                IsFeatured = true
            },
            new()
            {
                Id = 5, Code = "MATH 250", Title = "Linear Algebra",
                Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to computer graphics, data science, and engineering.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentCode = "MATH",
                InstructorName = "Prof. Emmy Noether", InstructorBio = "Prof. Noether is an expert in abstract algebra and its applications. She received the university's Outstanding Teaching Award three years in a row.",
                IsFeatured = false
            },
            new()
            {
                Id = 6, Code = "ENG 101", Title = "College Writing",
                Description = "Development of critical reading, analytical thinking, and effective writing skills. Students will write multiple essays exploring diverse topics and genres.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentCode = "ENG",
                InstructorName = "Dr. Virginia Woolf", InstructorBio = "Dr. Woolf specializes in modern literature and creative nonfiction. She has published two novels and numerous essays in literary journals.",
                IsFeatured = false
            },
            new()
            {
                Id = 7, Code = "ENG 220", Title = "American Literature",
                Description = "Survey of American literary works from the colonial period to the present, including novels, poetry, and drama. Emphasis on cultural and historical contexts.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentCode = "ENG",
                InstructorName = "Prof. Mark Twain", InstructorBio = "Prof. Twain brings a unique perspective on American literary traditions through his extensive research on 19th-century American authors and the evolution of the American novel.",
                IsFeatured = true
            },
            new()
            {
                Id = 8, Code = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Lecture and laboratory components explore Newton's laws, energy conservation, and oscillatory motion.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM, Lab: Fri 2:00–4:00 PM", DepartmentCode = "PHYS",
                InstructorName = "Dr. Marie Curie", InstructorBio = "Dr. Curie is a renowned physicist and educator with research interests in experimental physics and science pedagogy. She has received multiple grants for her work in undergraduate lab design.",
                IsFeatured = false
            },
            new()
            {
                Id = 9, Code = "PHYS 210", Title = "Modern Physics",
                Description = "Introduction to special relativity, quantum mechanics, atomic structure, and nuclear physics. Bridges classical and modern physical theories.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentCode = "PHYS",
                InstructorName = "Prof. Richard Feynman", InstructorBio = "Prof. Feynman is celebrated for his engaging lecture style and his contributions to quantum electrodynamics. He has been a faculty member for over a decade.",
                IsFeatured = false
            },
            new()
            {
                Id = 10, Code = "HIST 101", Title = "World History to 1500",
                Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the late medieval period. Examines political, social, and economic transformations across regions.",
                Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", DepartmentCode = "HIST",
                InstructorName = "Dr. Herodotus Khan", InstructorBio = "Dr. Khan is a historian of the ancient and medieval worlds, with expertise in cross-cultural interactions along the Silk Road. He regularly leads study-abroad programs.",
                IsFeatured = false
            },
            new()
            {
                Id = 11, Code = "HIST 250", Title = "The Modern Era",
                Description = "Exploration of global history from the Enlightenment to the present day. Topics include revolutions, industrialization, colonialism, world wars, and contemporary geopolitics.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentCode = "HIST",
                InstructorName = "Prof. Clio Historian", InstructorBio = "Prof. Historian specializes in 20th-century political history and has authored several books on the impact of global conflicts on modern nation-states.",
                IsFeatured = true
            },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? search = null, string? departmentCode = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

